-- Life plan simulator (ライフプラン): education and university cost tables, with seed rows.
-- All amounts are today's yen (no inflation). Values are national averages, not individual cases.

-- School education cost per child age (学習費総額, annual, yen). child_age = age in the school year
-- (3 = 幼稚園3歳, 6 = 小1, 12 = 中1, 15 = 高1, 17 = 高3).
CREATE TABLE education_costs (
    id            BIGSERIAL PRIMARY KEY,
    child_age     INTEGER       NOT NULL CHECK (child_age BETWEEN 3 AND 17),
    school_type   VARCHAR(10)   NOT NULL CHECK (school_type IN ('PUBLIC', 'PRIVATE')),
    annual_amount BIGINT        NOT NULL CHECK (annual_amount >= 0),
    fiscal_year   INTEGER       NOT NULL,
    source_label  VARCHAR(200)  NOT NULL,
    source_url    VARCHAR(2000) NOT NULL,
    verified_on   DATE          NOT NULL,
    note          VARCHAR(500)  NOT NULL DEFAULT '',
    created_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    UNIQUE (child_age, school_type, fiscal_year)
);

-- University tuition per year (yen). first_year_amount = 1st year (age 18), later_year_amount = 2nd to 4th year.
CREATE TABLE university_costs (
    id                BIGSERIAL PRIMARY KEY,
    university_type   VARCHAR(10)   NOT NULL CHECK (university_type IN ('NATIONAL', 'PRIVATE')),
    first_year_amount BIGINT        NOT NULL CHECK (first_year_amount >= 0),
    later_year_amount BIGINT        NOT NULL CHECK (later_year_amount >= 0),
    fiscal_year       INTEGER       NOT NULL,
    source_label      VARCHAR(200)  NOT NULL,
    source_url        VARCHAR(2000) NOT NULL,
    verified_on       DATE          NOT NULL,
    note              VARCHAR(500)  NOT NULL DEFAULT '',
    created_at        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    UNIQUE (university_type, fiscal_year)
);

