-- Seed: university tuition (授業料のみ。仕送り・通学費・一人暮らしの費用は含まない).
INSERT INTO university_costs (university_type, first_year_amount, later_year_amount, fiscal_year, source_label, source_url, verified_on, note) VALUES
('NATIONAL', 817800, 535800, 2025,
 '文部科学省 国立大学等の授業料その他の費用に関する省令 標準額',
 'https://www.mext.go.jp/content/20251226-mxt_sigakujo-000046463_4.pdf',
 DATE '2026-11-19',
 '初年度 = 授業料標準額535,800円 + 入学料標準額282,000円。2年目以降 = 授業料標準額535,800円。授業料のみ(仕送り・通学費・一人暮らしの費用は含まない)。省令: https://laws.e-gov.go.jp/law/416M60000080016'),
('PRIVATE', 1507647, 1170909, 2025,
 '文部科学省 私立大学等の令和7年度入学者に係る学生納付金等調査結果 私立大学(学部)の初年度学生納付金等の平均',
 'https://www.mext.go.jp/a_menu/koutou/shinkou/07021403/1412031_00006.htm',
 DATE '2026-11-19',
 '私立大学(学部)の平均で大学により大きく異なる。初年度 = 授業料968,069 + 入学料240,365 + 施設設備費172,550 + 実験実習料30,290 + その他96,374 の公表総計1,507,647円(内訳の合計は1,507,648円)。2年目以降は仮定: 授業料 + 施設設備費 + 実験実習料 = 1,170,909円(入学料とその他を除く)。授業料のみ(仕送り等は含まない)');
